def storage(page,key='compare'):return page.evaluate('(key)=>JSON.parse(localStorage.getItem("fretline:"+key)||"[]")',key)
def count(page,n):page.wait_for_function('(n)=>JSON.parse(localStorage.getItem("fretline:compare")||"[]").length===n',arg=n)
def visit(page,path):page.goto(BASE+path,wait_until='networkidle')
def select_answer(page,value):page.locator(f'label.quiz-option:has(input[value="{value}"])').click()
def next_step(page):page.get_by_role('button',name='ถัดไป',exact=True).click()

